class TrieNode {
  kids = new Map<string, TrieNode>();
  end = false;
}

class Trie {
  private root = new TrieNode();

  insert(word: string): void {
    let node = this.root;
    for (const c of word) {
      let next = node.kids.get(c);
      if (!next) {
        next = new TrieNode();
        node.kids.set(c, next);
      }
      node = next;
    }
    node.end = true;
  }

  // the node spelled by s, or null if the path breaks off
  private walk(s: string): TrieNode | null {
    let node = this.root;
    for (const c of s) {
      const next = node.kids.get(c);
      if (!next) return null;
      node = next;
    }
    return node;
  }

  search(word: string): boolean {
    const node = this.walk(word);
    return node !== null && node.end;
  }

  startsWith(prefix: string): boolean {
    return this.walk(prefix) !== null;
  }
}

