class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for c in word:
            if c not in node.kids:
                node.kids[c] = TrieNode()
            node = node.kids[c]
        node.end = True

    def _walk(self, s):
        """The node spelled by s, or None if the path breaks off."""
        node = self.root
        for c in s:
            node = node.kids.get(c)
            if node is None:
                return None
        return node

    def search(self, word: str) -> bool:
        node = self._walk(word)
        return node is not None and node.end

    def startsWith(self, prefix: str) -> bool:
        return self._walk(prefix) is not None

